use super::ExecutionDelta;
use serde::Serialize;
use std::path::{Path, PathBuf};
use super::executor_dispatch;
#[derive(Debug, Clone, Serialize)]
pub struct ExecutionDeltaOutcome {
    pub delta: ExecutionDelta,
    pub status: String,
    pub message: String,
}
#[derive(Debug, Clone)]
pub struct DeltaRepairAttempt {
    pub original: ExecutionDelta,
    pub repaired: ExecutionDelta,
    pub reason: String,
}
pub fn apply_read_deltas(
    deltas: &[ExecutionDelta],
    roots: &[PathBuf],
    max_output_lines: usize,
) -> (String, Vec<ExecutionDeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();
    for delta in deltas {
        let delta = repair_delta_pathing(delta, roots, &mut repairs);
        match executor_dispatch::execute_read_delta(&delta, roots, max_output_lines) {
            Ok((msg, out)) => {
                results
                    .push(ExecutionDeltaOutcome {
                        delta: delta.clone(),
                        status: "ok".into(),
                        message: msg,
                    });
                output.push_str(out.trim_end_matches('\n'));
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results
                    .push(ExecutionDeltaOutcome {
                        delta: delta.clone(),
                        status: "error".into(),
                        message: msg.clone(),
                    });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output
                .push_str(
                    &format!(
                        "{} => {} ({})\n", format_delta_label(& r.original),
                        format_delta_label(& r.repaired), r.reason
                    ),
                );
        }
    }
    (output, results, error)
}
pub fn summarize_execution_deltas(deltas: &[ExecutionDelta]) -> Vec<serde_json::Value> {
    deltas
        .iter()
        .map(|d| match d {
            ExecutionDelta::ReadFile { path } => {
                serde_json::json!({ "type" : "read_file", "path" : path })
            }
            ExecutionDelta::ListDir { path } => {
                serde_json::json!({ "type" : "list_dir", "path" : path })
            }
            ExecutionDelta::ReadCommand { command, args } => {
                serde_json::json!(
                    { "type" : "read_command", "command" : command, "args" : args }
                )
            }
            ExecutionDelta::WriteFile { path, .. } => {
                serde_json::json!({ "type" : "write_file", "path" : path })
            }
            ExecutionDelta::ReplaceText { path, .. } => {
                serde_json::json!({ "type" : "replace_text", "path" : path })
            }
            ExecutionDelta::DeleteFile { path } => {
                serde_json::json!({ "type" : "delete_file", "path" : path })
            }
        })
        .collect()
}
pub fn apply_write_deltas(
    deltas: &[ExecutionDelta],
    roots: &[PathBuf],
    allowed_write_roots: &[PathBuf],
    max_output_lines: usize,
) -> (String, Vec<ExecutionDeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();
    for delta in deltas {
        let delta = repair_delta_pathing(delta, roots, &mut repairs);
        match executor_dispatch::execute_write_delta(
            &delta,
            roots,
            allowed_write_roots,
            max_output_lines,
        ) {
            Ok(msg) => {
                results
                    .push(ExecutionDeltaOutcome {
                        delta: delta.clone(),
                        status: "ok".into(),
                        message: msg.clone(),
                    });
                output.push_str(&msg);
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results
                    .push(ExecutionDeltaOutcome {
                        delta: delta.clone(),
                        status: "error".into(),
                        message: msg.clone(),
                    });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output
                .push_str(
                    &format!(
                        "{} => {} ({})\n", format_delta_label(& r.original),
                        format_delta_label(& r.repaired), r.reason
                    ),
                );
        }
    }
    (output, results, error)
}
fn repair_delta_pathing(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    repairs: &mut Vec<DeltaRepairAttempt>,
) -> ExecutionDelta {
    let root = roots.get(0).cloned().unwrap_or_else(|| PathBuf::from("/"));
    match delta {
        ExecutionDelta::ReadFile { path } | ExecutionDelta::ListDir { path } => {
            let p = Path::new(path);
            if p.is_absolute() && !p.exists() {
                let repaired = match delta {
                    ExecutionDelta::ReadFile { .. } => {
                        ExecutionDelta::ReadFile {
                            path: root.display().to_string(),
                        }
                    }
                    ExecutionDelta::ListDir { .. } => {
                        ExecutionDelta::ListDir {
                            path: root.display().to_string(),
                        }
                    }
                    _ => delta.clone(),
                };
                repairs
                    .push(DeltaRepairAttempt {
                        original: delta.clone(),
                        repaired: repaired.clone(),
                        reason: "path does not exist; redirected to workspace root"
                            .to_string(),
                    });
                return repaired;
            }
            delta.clone()
        }
        _ => delta.clone(),
    }
}
fn format_delta_label(delta: &ExecutionDelta) -> String {
    match delta {
        ExecutionDelta::ReadFile { path } => format!("read_file {}", path),
        ExecutionDelta::ListDir { path } => format!("list_dir {}", path),
        ExecutionDelta::ReadCommand { command, args } => {
            format!("read_command {} {}", command, args.join(" "))
        }
        ExecutionDelta::WriteFile { path, .. } => format!("write_file {}", path),
        ExecutionDelta::ReplaceText { path, .. } => format!("replace_text {}", path),
        ExecutionDelta::DeleteFile { path } => format!("delete_file {}", path),
    }
}
pub(crate) fn resolve_delta_path(
    path: &str,
    roots: &[PathBuf],
    allow_nonexistent: bool,
) -> Result<PathBuf, String> {
    let p = Path::new(path);
    if delta_apply_has_parent_dir_component(&[path.to_string()]) {
        return Err(format!("path contains '..': {}", path));
    }
    let resolved = anchor_path(p, &roots[0]);
    if !delta_apply_is_within_roots(&resolved, roots) {
        return Err(format!("path escapes allowed roots: {}", resolved.display()));
    }
    if !allow_nonexistent && !resolved.exists() {
        return Err(format!("path does not exist: {}", resolved.display()));
    }
    Ok(resolved)
}
fn anchor_path(p: &Path, root: &Path) -> PathBuf {
    if p.is_absolute() { p.to_path_buf() } else { root.join(p) }
}
pub(crate) fn delta_apply_is_within_roots(path: &Path, roots: &[PathBuf]) -> bool {
    roots.iter().any(|root| path.starts_with(root))
}
pub(crate) fn delta_apply_has_parent_dir_component(args: &[String]) -> bool {
    args.iter().any(|a| a.split('/').any(|c| c == ".."))
}
pub(crate) fn delta_apply_truncate_lines(text: &str, max_lines: usize) -> String {
    let mut iter = text.lines();
    let kept: Vec<&str> = iter.by_ref().take(max_lines).collect();
    let remaining = iter.count();
    let mut out = kept.join("\n");
    if remaining > 0 {
        out.push_str(&format!("\n... [{} lines truncated] ...", remaining));
    }
    out
}

use std::collections::HashMap;
use std::path::Path;
use serde::{Deserialize, Serialize};
use super::capability::PipelineCapability;
use super::dag::ExecutionNode;
const COST_PATH: &str = "/workspace/ai_sandbox/canon/agent_logs/capability_costs.json";
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCost {
    pub latency_avg: f64,
    pub failure_rate: f64,
    pub samples: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCostCapabilityCostTable {
    pub costs: HashMap<PipelineCapability, CapabilityCost>,
}
impl CapabilityCostCapabilityCostTable {
    pub fn snapshot_store_load() -> Self {
        std::fs::read_to_string(COST_PATH)
            .ok()
            .and_then(|s| {
                serde_json::from_str::<CapabilityCostCapabilityCostTable>(&s).ok()
            })
            .unwrap_or_default()
    }
    pub fn snapshot_store_save(&self) {
        if let Ok(pretty) = serde_json::to_string_pretty(self) {
            let _ = std::fs::create_dir_all(
                Path::new(COST_PATH).parent().unwrap_or(Path::new(".")),
            );
            let _ = std::fs::write(COST_PATH, pretty);
        }
    }
    pub fn update(
        &mut self,
        cap: PipelineCapability,
        latency_ms: f64,
        success: bool,
        decay: f64,
    ) {
        let decay = decay.clamp(0.0, 1.0);
        let entry = self.costs.entry(cap).or_default();
        let failure = if success { 0.0 } else { 1.0 };
        if entry.samples == 0 {
            entry.latency_avg = latency_ms;
            entry.failure_rate = failure;
        } else {
            entry.latency_avg = (1.0 - decay) * entry.latency_avg + decay * latency_ms;
            entry.failure_rate = (1.0 - decay) * entry.failure_rate + decay * failure;
        }
        entry.samples = entry.samples.saturating_add(1);
    }
    pub fn node_cost(
        &self,
        caps: &[PipelineCapability],
        latency_weight: f64,
        failure_weight: f64,
    ) -> f64 {
        caps.iter()
            .map(|c| self.costs.get(c))
            .flatten()
            .map(|c| latency_weight * c.latency_avg + failure_weight * c.failure_rate)
            .sum()
    }
    pub fn avg_latency(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.latency_avg;
                count += 1;
            }
        }
        if count == 0 { 0.0 } else { total / count as f64 }
    }
    pub fn avg_failure(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.failure_rate;
                count += 1;
            }
        }
        if count == 0 { 0.0 } else { total / count as f64 }
    }
    pub fn summary(
        &self,
        max_entries: usize,
        latency_weight: f64,
        failure_weight: f64,
    ) -> String {
        let mut entries: Vec<(PipelineCapability, f64, f64, f64)> = self
            .costs
            .iter()
            .map(|(cap, cost)| {
                let score = latency_weight * cost.latency_avg
                    + failure_weight * cost.failure_rate;
                (*cap, cost.latency_avg, cost.failure_rate, score)
            })
            .collect();
        entries
            .sort_by(|a, b| b.3.partial_cmp(&a.3).unwrap_or(std::cmp::Ordering::Equal));
        entries.truncate(max_entries);
        let mut lines = Vec::new();
        for (cap, lat, fail, score) in entries {
            lines
                .push(
                    format!(
                        "{:?}: latency_ms={:.1} fail_rate={:.2} cost={:.2}", cap, lat,
                        fail, score
                    ),
                );
        }
        lines.join("\n")
    }
}
pub fn capability_cost_apply_node_cost_update(
    table: &mut CapabilityCostCapabilityCostTable,
    node: &ExecutionNode,
    latency_ms: f64,
    success: bool,
    decay: f64,
    latency_weight: f64,
    failure_weight: f64,
) -> f64 {
    for cap in &node.required_capabilities {
        table.update(*cap, latency_ms, success, decay);
    }
    table.node_cost(&node.required_capabilities, latency_weight, failure_weight)
}

