const PENDING_TO_READY: [NodeStatus; 6] = [
    NodeStatus::Ready,
    NodeStatus::Ready,
    NodeStatus::Running,
    NodeStatus::Completed,
    NodeStatus::Failed,
    NodeStatus::Blocked,
];
const TRANSITION_TABLE: [[bool; 6]; 6] = {
    let mut t = [[false; 6]; 6];
    t[0][1] = true;
    t[0][5] = true;
    t[1][2] = true;
    t[2][1] = true;
    t[2][3] = true;
    t[2][4] = true;
    t[5][1] = true;
