#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExecutionGraph {
    pub nodes: Vec<ExecutionNode>,
    #[serde(skip, default)]
    pub id_index: HashMap<String, usize>,
}
impl ExecutionGraph {
    pub fn new() -> Self {
        Self {
            nodes: Vec::new(),
            id_index: HashMap::new(),
        }
    }
    pub fn add_node(&mut self, node: ExecutionNode) {
        let idx = self.nodes.len();
        self.id_index.insert(node.id.clone(), idx);
        self.nodes.push(node);
    }
    pub fn rebuild_index(&mut self) {
        self.id_index.clear();
        for (idx, node) in self.nodes.iter().enumerate() {
            self.id_index.insert(node.id.clone(), idx);
        }
    }
    fn ensure_index(&mut self) {
        if self.id_index.len() != self.nodes.len() {
            self.rebuild_index();
        }
    }
    pub fn get_node(&mut self, id: &str) -> Option<&ExecutionNode> {
        self.ensure_index();
        let idx = *self.id_index.get(id)?;
        self.nodes.get(idx)
    }
    pub fn get_node_mut(&mut self, id: &str) -> Option<&mut ExecutionNode> {
        self.ensure_index();
        let idx = *self.id_index.get(id)?;
        self.nodes.get_mut(idx)
    }
    pub fn ready_nodes(&self) -> Vec<&ExecutionNode> {
        self.nodes.iter().filter(|n| n.status == NodeStatus::Ready).collect()
    }
    pub fn all_completed(&self) -> bool {
        !self.nodes.is_empty()
            && self.nodes.iter().all(|n| n.status == NodeStatus::Completed)
    }
    pub fn has_failed(&self) -> bool {
        self.nodes.iter().any(|n| n.status == NodeStatus::Failed)
    }
    pub fn update_status(&mut self, id: &str, status: NodeStatus) -> Result<(), String> {
        let node = self
            .get_node_mut(id)
            .ok_or_else(|| format!("unknown node id: {id}"))?;
        if !task_graph_transition_allowed(node.status, status) {
            return Err(
                format!(
                    "invalid status transition: {:?} -> {:?} for {}", node.status,
                    status, id
                ),
            );
        }
        node.status = status;
        Ok(())
    }
    pub fn validate(&self) -> Result<(), String> {
        let mut seen = HashSet::new();
        for n in &self.nodes {
            if !seen.insert(n.id.clone()) {
                return Err(format!("duplicate node id: {}", n.id));
            }
        }
        let ids: HashSet<&str> = self.nodes.iter().map(|n| n.id.as_str()).collect();
        for n in &self.nodes {
            for d in &n.deps {
                if !ids.contains(d.as_str()) {
                    return Err(format!("node {} references unknown dep {}", n.id, d));
                }
            }
        }
        for n in &self.nodes {
            let caps: HashSet<PipelineCapability> = n
                .required_capabilities
                .iter()
                .copied()
                .collect();
            capability_model_assert_class_disjoint(&caps)
                .map_err(|e| format!("node {}: {}", n.id, e))?;
        }
        task_graph_detect_cycle(self)?;
        Ok(())
    }
    pub fn reset_for_execution(&mut self) {
        for node in &mut self.nodes {
            node.status = NodeStatus::Pending;
            node.result = None;
            node.error = None;
            node.readonly_fail_count = 0;
            node.completed_iter = None;
        }
        self.rebuild_index();
    }
}
fn task_graph_transition_allowed(from: NodeStatus, to: NodeStatus) -> bool {
    TRANSITION_TABLE[from as usize][to as usize]
}
fn task_graph_detect_cycle(graph: &ExecutionGraph) -> Result<(), String> {
    let id_to_idx: HashMap<&str, usize> = graph
        .nodes
        .iter()
        .enumerate()
        .map(|(i, n)| (n.id.as_str(), i))
        .collect();
    let adj: Vec<Vec<usize>> = graph
        .nodes
        .iter()
        .map(|n| {
            n.deps.iter().filter_map(|d| id_to_idx.get(d.as_str()).copied()).collect()
        })
        .collect();
    let sccs = algorithms::graph::scc::kosaraju_scc(&adj);
    if sccs.iter().any(|c| c.len() > 1) {
        return Err("cycle detected in task graph".into());
    }
    Ok(())
}
#[derive(Debug, Clone)]
pub struct NodeAuthority {
    pub node_id: String,
    pub capabilities: HashSet<PipelineCapability>,
}
impl NodeAuthority {
    pub fn new(
        node_id: String,
        caps: HashSet<PipelineCapability>,
    ) -> Result<Self, String> {
        capability_model_assert_class_disjoint(&caps)?;
        Ok(Self {
            node_id,
            capabilities: caps,
        })
    }
    pub fn has(&self, cap: PipelineCapability) -> bool {
        self.capabilities.contains(&cap)
    }
    pub fn require(&self, cap: PipelineCapability) -> Result<(), String> {
        if self.has(cap) {
            Ok(())
        } else {
            Err(format!("node {} missing capability {:?}", self.node_id, cap))
        }
    }
    pub fn is_verify_context(&self) -> bool {
        self.capabilities.iter().any(|c| c.class() == CapabilityMode::Verify)
    }
    pub fn is_mutation_context(&self) -> bool {
        self.capabilities.iter().any(|c| c.class() == CapabilityMode::Mutate)
    }
}
pub fn task_graph_resolve_ready(graph: &mut ExecutionGraph) {
    let completed: std::collections::HashSet<String> = graph
        .nodes
        .iter()
        .filter(|n| n.status == NodeStatus::Completed)
        .map(|n| n.id.clone())
        .collect();
    for node in &mut graph.nodes {
        if node.status != NodeStatus::Pending {
            continue;
        }
        let deps_satisfied = node.deps.iter().all(|d| completed.contains(d));
        if deps_satisfied {
            node.status = PENDING_TO_READY[node.status as usize];
        }
    }
}
pub fn task_graph_grant_authority(
    node: &ExecutionNode,
) -> Result<NodeAuthority, String> {
    let caps: std::collections::HashSet<PipelineCapability> = node
        .required_capabilities
        .iter()
        .copied()
        .collect();
    NodeAuthority::new(node.id.clone(), caps)
}

