    let (endpoint_id, url, max_tabs) = selected
        .get(0)
        .map(|e| (e.id.clone(), e.url.clone(), e.max_tabs))
        .unwrap_or_else(|| (fallback.0.to_string(), fallback.1.to_string(), fallback.2));
    NodeDispatchContext {
        endpoint_id,
        url,
        max_tabs,
        stateful: fallback.3,
        workspace_root,
        log_dir,
    }
}
