pub async fn dispatch_node_execution(
    node: ExecutionNode,
    auth: NodeAuthority,
    bridge: &WsBridge,
    tabs: &TabManagerHandle,
    sem: Arc<Semaphore>,
    ctx: NodeDispatchContext,
    context: Vec<ContextSnapshotNode>,
    iter: u64,
    retry_count: u32,
    retry_delay: u64,
    tab_cooldown_ms: u64,
) -> Result<(String, Result<engine::ModuleNodeCallResult>, Duration)> {
    let start = std::time::Instant::now();
    let _permit = sem.acquire().await.map_err(|_| anyhow::anyhow!("semaphore closed"))?;
    let res = engine::module_call_node(
            &node,
            &auth,
            bridge,
            &ctx.endpoint_id,
            &ctx.url,
            ctx.stateful,
            "",
            tabs,
            ctx.max_tabs,
            tab_cooldown_ms,
            &ctx.workspace_root,
            &context,
            &ctx.log_dir,
            iter,
            retry_count,
            retry_delay,
        )
        .await;
    Ok((node.id.clone(), res, start.elapsed()))
}

use std::collections::HashMap;
use super::config::CapabilityConfig;
#[derive(Clone)]
pub struct EndpointSelection {
    pub id: String,
    pub url: String,
    pub max_tabs: usize,
}
pub fn role_burst_limit(config: &CapabilityConfig, role: &str) -> usize {
    let role_cfg = config.role_config(role);
    role_cfg.burst.unwrap_or_else(|| config.max_concurrency.max(1))
}
pub async fn endpoint_selector_select_endpoints_for_role(
    config: &CapabilityConfig,
    role_rr: &tokio::sync::Mutex<HashMap<String, usize>>,
    role: &str,
    burst: usize,
) -> Vec<EndpointSelection> {
    let role_cfg = config.role_config(role);
    let mut weights: Vec<(usize, u32)> = Vec::new();
    let mut total = 0u32;
    for (idx, ep) in config.llm_endpoints.iter().enumerate() {
        if let Some(ep_role) = ep.role.as_deref() {
            if ep_role != role {
                continue;
            }
        }
        let w = role_cfg.weights.get(&ep.id).copied().unwrap_or(0);
        if w > 0 {
            weights.push((idx, w));
            total += w;
        }
    }
    let use_default_weights = total == 0;
    if use_default_weights {
        for (idx, _ep) in config.llm_endpoints.iter().enumerate() {
            if let Some(ep_role) = config.llm_endpoints[idx].role.as_deref() {
                if ep_role != role {
                    continue;
                }
            }
            weights.push((idx, 1));
            total += 1;
        }
    }
    if weights.is_empty() {
        return Vec::new();
    }
    let mut selected = Vec::with_capacity(burst.max(1));
    for _ in 0..burst.max(1) {
        let idx = {
            let mut rr = role_rr.lock().await;
            let entry = rr.entry(role.to_string()).or_insert(0);
            let sel = *entry % (total as usize);
            *entry = entry.wrapping_add(1);
            sel
        };
        let chosen = weights
            .iter()
            .scan(
                0usize,
                |acc, &(ep_idx, w)| {
                    *acc += w as usize;
                    Some((*acc, ep_idx))
                },
            )
            .find_map(|(acc, ep_idx)| (idx < acc).then_some(ep_idx))
            .unwrap_or(weights[0].0);
        let ep = &config.llm_endpoints[chosen];
        selected
            .push(EndpointSelection {
                id: ep.id.clone(),
                url: ep.url.clone(),
                max_tabs: ep.max_tabs,
            });
    }
    selected
}

use std::collections::{HashMap, HashSet};
use std::hash::{Hash, Hasher};
