async fn module_call_mode(
    mode: ModuleDispatchMode,
    node: &ExecutionNode,
    bridge: &WsBridge,
    endpoint_id: &str,
    url: &str,
    stateful: bool,
    role_schema: &str,
    tabs: &TabManagerHandle,
    max_tabs: usize,
    tab_cooldown_ms: u64,
    workspace_root: &Path,
    context: &[ContextSnapshotNode],
    log_dir: &Path,
    iter: u64,
    retries: u32,
    delay_secs: u64,
) -> Result<ModuleNodeCallResult> {
    let config = &MODE_CONFIGS[mode as usize];
    let input: Value = match mode {
        ModuleDispatchMode::Mutate => {
            serde_json::json!(
                { "nodes" : [{ "id" : node.id, "description" : node.description,
                "node_type" : node.node_type, "deps" : node.deps, "required_capabilities"
                : node.required_capabilities }], "context" : context }
            )
        }
        ModuleDispatchMode::Verify => {
            serde_json::json!(
                { "nodes" : [{ "id" : node.id, "status" : node.status, "result" : node
                .result, "description" : node.description }], "context" : context }
            )
        }
        ModuleDispatchMode::Readonly => {
            serde_json::json!(
                { "node" : { "id" : node.id, "description" : node.description,
                "node_type" : node.node_type, "deps" : node.deps, "required_capabilities"
                : node.required_capabilities }, "context" : context }
            )
        }
    };
    let prompt = format!(
        "{}\n\nWorkspace root: {}\nContext radius: {} nodes.\nINPUT:\n{}", config.schema,
        workspace_root.display(), context.len(), serde_json::to_string_pretty(& input)
        .unwrap_or_default()
    );
    let payload = module_llm_call_with_retry(
            bridge,
            endpoint_id,
            url,
            stateful,
            &prompt,
            config.schema,
            &input,
            role_schema,
            config.phase,
            Some(&node.id),
            tabs,
            max_tabs,
            tab_cooldown_ms,
            retries,
            delay_secs,
        )
        .await?;
    if let Ok(pretty) = serde_json::to_string_pretty(&payload) {
        let _ = std::fs::write(log_dir.join((config.log_name)(iter)), pretty);
    }
    let parse_fn = PARSE_FNS[mode as usize];
    parse_fn(payload, node, iter)
}
async fn module_llm_call_with_retry(
    bridge: &WsBridge,
    endpoint_id: &str,
    url: &str,
    stateful: bool,
    prompt: &str,
    schema: &str,
    input: &Value,
    role_schema: &str,
    phase: &str,
    node_id: Option<&str>,
    tabs: &TabManagerHandle,
    max_tabs: usize,
    tab_cooldown_ms: u64,
    retries: u32,
    delay_secs: u64,
) -> Result<Value> {
    let payload = llm_client_call_agent_json_with_retry_allow_mismatch(
            bridge,
            endpoint_id,
            url,
            stateful,
            prompt,
            role_schema,
            phase,
            node_id,
            tabs,
            max_tabs,
            tab_cooldown_ms,
            retries,
            delay_secs,
        )
        .await?;
    Ok(payload)
}
fn module_apply_mutate_output(
    node_id: String,
    output: ModuleExecOutput,
    graph: &mut ExecutionGraph,
    roots: &[PathBuf],
    max_output_lines: usize,
    _log_dir: &Path,
    iter: u64,
    policy: &CapabilityConfigCapabilityPolicy,
) -> Result<()> {
    if module_mutate_is_blocked(&node_id, graph, policy) {
        eprintln!(
            r#"[capability] {{"iter":{},"phase":"executor","event":"render_blocked","node":"{}"}}"#,
            iter, node_id
        );
        let _ = graph.update_status(&node_id, NodeStatus::Ready);
        return Ok(());
    }
    for mut result in output.results {
        module_coerce_id(&mut result.id, &node_id);
        module_apply_mutate_result(
            result,
            &node_id,
            graph,
            roots,
            max_output_lines,
            iter,
        );
    }
    Ok(())
}
fn module_apply_verify_output(
    node_id: String,
    output: ModuleVerifyOutput,
    graph: &mut ExecutionGraph,
    _log_dir: &Path,
    iter: u64,
) -> Result<()> {
    for mut upd in output.updates {
        module_coerce_id(&mut upd.id, &node_id);
        let _ = graph.update_status(&upd.id, upd.status);
        if let Some(n) = graph.get_node_mut(&upd.id) {
            n.error = upd.error;
            if upd.status == NodeStatus::Completed {
                n.completed_iter = Some(iter);
            }
        }
    }
    if let Some(node) = graph.get_node_mut(&node_id) {
        let has_mutate = node
            .required_capabilities
            .iter()
            .any(|c| c.class() == CapabilityMode::Mutate);
        let has_observe = node
            .required_capabilities
            .iter()
            .any(|c| c.class() == CapabilityMode::Observe);
        let has_verify = node
            .required_capabilities
            .iter()
            .any(|c| c.class() == CapabilityMode::Verify);
        if has_verify && !has_mutate && !has_observe && node.status == NodeStatus::Ready
        {
            let _ = graph.update_status(&node_id, NodeStatus::Completed);
            if let Some(n) = graph.get_node_mut(&node_id) {
                n.completed_iter = Some(iter);
            }
            eprintln!(
                "{}", console::console_ui_phase("verify", &
                format!("node={} auto-completed verify-only", node_id))
            );
        }
    }
    Ok(())
}
fn module_apply_readonly_output(
    node_id: String,
    output: ModuleExecOutput,
    graph: &mut ExecutionGraph,
    roots: &[PathBuf],
    max_output_lines: usize,
    log_dir: &Path,
    iter: u64,
    max_node_retries: u32,
) -> Result<()> {
    output
        .results
        .is_empty()
        .then(|| module_log_empty_readonly(iter, &node_id, log_dir))
        .and_then(|_| graph.update_status(&node_id, NodeStatus::Ready).ok());
    for mut result in output.results {
        module_coerce_id(&mut result.id, &node_id);
        module_apply_readonly_result(
            result,
            &node_id,
            graph,
            roots,
            max_output_lines,
            log_dir,
            iter,
            max_node_retries,
        );
    }
    Ok(())
}
fn module_partition_deltas(
    deltas: Vec<ExecutionDelta>,
) -> (Vec<ExecutionDelta>, Vec<ExecutionDelta>) {
    deltas
        .into_iter()
        .partition(|d| {
            matches!(
                d, ExecutionDelta::ReadFile { .. } | ExecutionDelta::ListDir { .. } |
                ExecutionDelta::ReadCommand { .. }
            )
        })
}
fn module_mutate_is_blocked(
    node_id: &str,
    graph: &ExecutionGraph,
    policy: &CapabilityConfigCapabilityPolicy,
) -> bool {
    let not_render = graph
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .map(|n| n.node_type != super::decompose::DecomposeNodeType::Render)
        .unwrap_or(false);
    let render_blocked = policy.require_final_render
        && graph
            .nodes
            .iter()
            .any(|n| {
                n.status != NodeStatus::Completed
                    && !n
                        .required_capabilities
                        .iter()
                        .any(|c| c.class() == CapabilityMode::Mutate)
            });
    not_render || render_blocked
}
fn module_apply_mutate_result(
    result: ModuleExecNodeResult,
    node_id: &str,
    graph: &mut ExecutionGraph,
    roots: &[PathBuf],
    max_output_lines: usize,
    iter: u64,
) {
    if !result.rationale.trim().is_empty() {
        eprintln!(
            "{}", console::console_ui_phase("mutate", & format!("node={} rationale={}",
            node_id, console::console_ui_truncate(& result.rationale, 180)))
        );
    }
    let (ro, mutate) = module_partition_deltas(result.deltas);
    if !ro.is_empty() {
        let _ = apply_read_deltas(&ro, roots, max_output_lines);
    }
    let (out, _, err) = apply_write_deltas(&mutate, roots, roots, max_output_lines);
    let _ = graph.update_status(node_id, NodeStatus::Running);
    let (requires_verify, has_err) = if let Some(n) = graph.get_node_mut(node_id) {
        n.result = Some(out);
        n.error = err;
        (
            n.required_capabilities.iter().any(|c| c.class() == CapabilityMode::Verify),
            n.error.is_some(),
        )
    } else {
        (false, false)
    };
    let final_status = requires_verify
        .then_some(None)
        .unwrap_or_else(|| Some(
            if has_err { NodeStatus::Failed } else { NodeStatus::Completed },
        ));
    if let Some(s) = final_status {
        let _ = graph.update_status(node_id, s);
        if s == NodeStatus::Completed {
            if let Some(n) = graph.get_node_mut(node_id) {
                n.completed_iter = Some(iter);
            }
        }
    }
}
fn module_log_empty_readonly(iter: u64, node_id: &str, log_dir: &Path) {
    let summary = serde_json::json!(
        { "iter" : iter, "phase" : "readonly", "event" : "empty_results", "node" :
        node_id }
    );
    let _ = std::fs::write(
        log_dir.join(format!("iter_{:03}_readonly_error.json", iter)),
        serde_json::to_string_pretty(&summary).unwrap_or_default(),
    );
    eprintln!("[capability] {}", summary);
}
fn module_log_readonly_error(
    iter: u64,
    node_id: &str,
    err: &str,
    deltas: &[ExecutionDelta],
    log_dir: &Path,
) {
    let summary = serde_json::json!(
        { "iter" : iter, "phase" : "readonly", "event" : "delta_error", "node" : node_id,
        "error" : err, "deltas" : summarize_execution_deltas(deltas) }
    );
    let _ = std::fs::write(
        log_dir.join(format!("iter_{:03}_readonly_error.json", iter)),
        serde_json::to_string_pretty(&summary).unwrap_or_default(),
    );
    eprintln!("[capability] {}", summary);
}
fn module_apply_readonly_result(
    result: ModuleExecNodeResult,
    node_id: &str,
    graph: &mut ExecutionGraph,
    roots: &[PathBuf],
    max_output_lines: usize,
    log_dir: &Path,
    iter: u64,
    max_node_retries: u32,
) {
    if !result.rationale.trim().is_empty() {
        eprintln!(
            "{}", console::console_ui_phase("observe", & format!("node={} rationale={}",
            node_id, console::console_ui_truncate(& result.rationale, 180)))
        );
    }
    let (ro, mutate) = module_partition_deltas(result.deltas);
    if !mutate.is_empty() {
        let msg = "read-only context received mutation deltas".to_string();
        if let Some(n) = graph.get_node_mut(node_id) {
            n.result = Some(msg.clone());
            n.error = Some(msg);
        }
        let _ = graph.update_status(node_id, NodeStatus::Failed);
        return;
    }
    let (out, _, err) = apply_read_deltas(&ro, roots, max_output_lines);
    let _ = graph.update_status(node_id, NodeStatus::Running);
    if let Some(n) = graph.get_node_mut(node_id) {
        n.result = Some(out);
        n.error = err.clone();
    }
    let effective_budget = graph
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .and_then(|n| n.budget)
        .unwrap_or(max_node_retries);
    let next_status = err
        .map(|e| {
            module_log_readonly_error(iter, node_id, &e, &ro, log_dir);
            let fail_count = graph
                .get_node_mut(node_id)
                .map(|n| {
                    n.readonly_fail_count += 1;
                    n.readonly_fail_count
                })
                .unwrap_or(1);
            if fail_count >= effective_budget {
                NodeStatus::Failed
            } else {
                NodeStatus::Ready
            }
        })
        .unwrap_or(NodeStatus::Completed);
    let _ = graph.update_status(node_id, next_status);
    if next_status == NodeStatus::Completed {
        if let Some(n) = graph.get_node_mut(node_id) {
            n.completed_iter = Some(iter);
        }
    }
}
fn module_coerce_id(result_id: &mut String, canonical: &str) {
    result_id.clear();
    result_id.push_str(canonical);
}
fn module_parse_exec_output(
    payload: &Value,
    default_id: &str,
) -> Result<ModuleExecOutput> {
    if let Ok(v) = serde_json::from_value::<ModuleExecOutput>(payload.clone()) {
        return Ok(v);
    }
    if let Some(deltas) = payload.get("deltas") {
        let deltas: Vec<ExecutionDelta> = serde_json::from_value(deltas.clone())
            .context("executor deltas field invalid")?;
        let rationale = payload
            .get("rationale")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let id = payload
            .get("id")
            .and_then(|v| v.as_str())
            .unwrap_or(default_id)
            .to_string();
        return Ok(ModuleExecOutput {
            results: vec![ModuleExecNodeResult { id, deltas, rationale }],
        });
    }
    Err(anyhow::anyhow!("executor output did not match schema"))
}

use std::path::Path;
use super::capability_cost::{
    capability_cost_apply_node_cost_update, CapabilityCostCapabilityCostTable,
};
use super::config;
use super::dag;
use super::engine;
use super::telemetry::ExecutionTelemetry;
use super::LOG_ROOT;
use anyhow::Result;
#[derive(Default)]
pub struct RepairAttemptStats {
    pub attempts: u64,
    pub successes: u64,
    pub last_kind: Option<String>,
}
pub fn apply_node_result(
    item: Result<(String, Result<engine::ModuleNodeCallResult>, std::time::Duration)>,
    graph: &mut dag::ExecutionGraph,
    cwd: &[std::path::PathBuf],
    max_output_lines: usize,
    iter: u64,
    policy: &config::CapabilityConfigCapabilityPolicy,
    exec_metrics: &mut ExecutionTelemetry,
    repair_stats: &mut RepairAttemptStats,
    repair_radius: usize,
    max_repairs: u32,
    cost_table: &mut CapabilityCostCapabilityCostTable,
    cost_decay_rate: f64,
    cost_latency_weight: f64,
    cost_failure_weight: f64,
) -> Option<u128> {
    let (node_id, call_result, elapsed) = match item {
        Ok(t) => t,
        Err(e) => {
            eprintln!(
                r#"[capability] {{"iter":{},"event":"join_error","error":"{}"}}"#, iter,
                e
            );
            return None;
        }
    };
    let ms = elapsed.as_millis();
    let report = match engine::module_process_call_result(
        node_id.clone(),
        call_result,
        graph,
        cwd,
        max_output_lines,
        Path::new(LOG_ROOT),
        iter,
        policy,
        repair_radius,
        max_repairs,
    ) {
        Ok(report) => report,
        Err(e) => {
            eprintln!(
                r#"[capability] {{"iter":{},"event":"call_or_apply_error","node":"{}","error":"{}"}}"#,
                iter, node_id, e
            );
            return None;
        }
    };
    if report.had_error {
        repair_stats.attempts += 1;
        if report.repair_succeeded {
            repair_stats.successes += 1;
        }
        repair_stats.last_kind = report.repair_kind.clone();
        exec_metrics.nodes_failed += 1;
    }
    if let Some(n) = graph.get_node_mut(&node_id) {
        let success = matches!(n.status, dag::NodeStatus::Completed);
        let latency_ms = ms as f64;
        let _node_cost = capability_cost_apply_node_cost_update(
            cost_table,
            n,
            latency_ms,
            success,
            cost_decay_rate,
            cost_latency_weight,
            cost_failure_weight,
        );
    }
    Some(ms)
}

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use once_cell::sync::Lazy;
use super::act::{
    delta_apply_has_parent_dir_component, delta_apply_is_within_roots,
    resolve_delta_path, delta_apply_truncate_lines,
};
use super::ExecutionDelta;
type DeltaExecutorReadHandler = fn(
    &ExecutionDelta,
    &[PathBuf],
    usize,
) -> Result<(String, String), String>;
type DeltaExecutorWriteHandler = fn(
    &ExecutionDelta,
    &[PathBuf],
    &[PathBuf],
    usize,
) -> Result<String, String>;
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum ExecutionDeltaType {
    ReadFile,
    ListDir,
    ReadCommand,
    WriteFile,
    ReplaceText,
    DeleteFile,
}
static READ_EXECUTORS: Lazy<HashMap<ExecutionDeltaType, DeltaExecutorReadHandler>> = Lazy::new(||
{
    let mut map: HashMap<ExecutionDeltaType, DeltaExecutorReadHandler> = HashMap::new();
    map.insert(
        ExecutionDeltaType::ReadFile,
        apply_read_file as DeltaExecutorReadHandler,
    );
    map.insert(ExecutionDeltaType::ListDir, apply_list_dir as DeltaExecutorReadHandler);
    map.insert(
        ExecutionDeltaType::ReadCommand,
        apply_read_command as DeltaExecutorReadHandler,
    );
    map
});
static WRITE_EXECUTORS: Lazy<HashMap<ExecutionDeltaType, DeltaExecutorWriteHandler>> = Lazy::new(||
{
    let mut map: HashMap<ExecutionDeltaType, DeltaExecutorWriteHandler> = HashMap::new();
    map.insert(
        ExecutionDeltaType::WriteFile,
        apply_write_file as DeltaExecutorWriteHandler,
    );
    map.insert(
        ExecutionDeltaType::ReplaceText,
        apply_replace_text as DeltaExecutorWriteHandler,
    );
    map.insert(
        ExecutionDeltaType::DeleteFile,
        apply_delete_file as DeltaExecutorWriteHandler,
    );
    map
});
const READONLY_COMMANDS: &[&str] = &[
    "rg",
    "cat",
    "ls",
    "find",
    "head",
    "tail",
    "wc",
    "stat",
    "sed",
    "awk",
    "pwd",
    "tree",
];
pub fn execute_read_delta(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    max_output_lines: usize,
) -> Result<(String, String), String> {
    let kind = delta_executor_delta_type(delta);
    let handler = READ_EXECUTORS
        .get(&kind)
        .ok_or_else(|| "read_only delta type not allowed in this phase".to_string())?;
    handler(delta, roots, max_output_lines)
}
pub fn execute_write_delta(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    allowed_write_roots: &[PathBuf],
    max_output_lines: usize,
) -> Result<String, String> {
    let kind = delta_executor_delta_type(delta);
    let handler = WRITE_EXECUTORS
        .get(&kind)
        .ok_or_else(|| "mutation delta type not allowed in this phase".to_string())?;
    handler(delta, roots, allowed_write_roots, max_output_lines)
}
fn delta_executor_delta_type(delta: &ExecutionDelta) -> ExecutionDeltaType {
    match delta {
        ExecutionDelta::ReadFile { .. } => ExecutionDeltaType::ReadFile,
        ExecutionDelta::ListDir { .. } => ExecutionDeltaType::ListDir,
        ExecutionDelta::ReadCommand { .. } => ExecutionDeltaType::ReadCommand,
        ExecutionDelta::WriteFile { .. } => ExecutionDeltaType::WriteFile,
        ExecutionDelta::ReplaceText { .. } => ExecutionDeltaType::ReplaceText,
        ExecutionDelta::DeleteFile { .. } => ExecutionDeltaType::DeleteFile,
    }
}
fn apply_read_file(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    max_output_lines: usize,
) -> Result<(String, String), String> {
    let ExecutionDelta::ReadFile { path } = delta else {
        return Err("read_file handler received wrong delta".into());
    };
    let path = resolve_delta_path(path, roots, false)?;
    if path.is_dir() {
        return apply_list_dir(
            &ExecutionDelta::ListDir {
                path: path.display().to_string(),
            },
            roots,
            max_output_lines,
        );
    }
    let content = fs::read_to_string(&path)
        .map_err(|e| format!("read_file failed for {}: {e}", path.display()))?;
    let out = format!(
        "[read_file {}]\n{}\n", path.display(), delta_apply_truncate_lines(& content,
        max_output_lines)
    );
    Ok((format!("read_file {}", path.display()), out))
}
fn apply_list_dir(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    max_output_lines: usize,
) -> Result<(String, String), String> {
    let ExecutionDelta::ListDir { path } = delta else {
        return Err("list_dir handler received wrong delta".into());
    };
    let path = resolve_delta_path(path, roots, false)?;
    let mut entries: Vec<String> = fs::read_dir(&path)
        .map_err(|e| format!("list_dir failed for {}: {e}", path.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().to_string())
        .collect();
    entries.sort();
    let out = format!("[list_dir {}]\n{}\n", path.display(), entries.join("\n"));
    Ok((
        format!("list_dir {}", path.display()),
        delta_apply_truncate_lines(&out, max_output_lines),
    ))
}
fn apply_read_command(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    max_output_lines: usize,
) -> Result<(String, String), String> {
    let ExecutionDelta::ReadCommand { command, args } = delta else {
        return Err("read_command handler received wrong delta".into());
    };
    if !READONLY_COMMANDS.iter().any(|c| c == command) {
        return Err(format!("read_command rejected: {} not in whitelist", command));
    }
    if delta_apply_has_parent_dir_component(args) {
        return Err("read_command args contain '..'".into());
    }
    let output = Command::new(command)
        .args(args)
        .current_dir(&roots[0])
        .output()
        .map_err(|e| format!("read_command failed to spawn: {e}"))?;
    let mut combined = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr);
    if !stderr.trim().is_empty() {
        if !combined.is_empty() {
            combined.push('\n');
        }
        combined.push_str("--- stderr ---\n");
        combined.push_str(&stderr);
    }
    let code = output.status.code().unwrap_or(1);
    if code != 0 {
        combined.push_str(&format!("\n[exit code {}]", code));
    }
    let out = format!(
        "[read_command {} {}]\n{}\n", command, args.join(" "),
        delta_apply_truncate_lines(& combined, max_output_lines)
    );
    Ok((format!("read_command {}", command), out))
}
fn apply_write_file(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    allowed_write_roots: &[PathBuf],
    _max_output_lines: usize,
) -> Result<String, String> {
    let ExecutionDelta::WriteFile { path, content } = delta else {
        return Err("write_file handler received wrong delta".into());
    };
    let path = resolve_delta_path(path, roots, true)?;
    if !delta_apply_is_within_roots(&path, allowed_write_roots) {
        return Err(
            format!("write_file refused outside allowed roots: {}", path.display()),
        );
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|e| format!("write_file failed to create parent dirs: {e}"))?;
    }
    let existing = fs::read_to_string(&path).unwrap_or_default();
    if existing == *content {
        return Ok(format!("write_file {} (no-op)", path.display()));
    }
    fs::write(&path, content)
        .map_err(|e| format!("write_file failed for {}: {e}", path.display()))?;
    Ok(format!("write_file {} ({} bytes)", path.display(), content.len()))
}
fn apply_replace_text(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    allowed_write_roots: &[PathBuf],
    _max_output_lines: usize,
) -> Result<String, String> {
    let ExecutionDelta::ReplaceText { path, find, replace } = delta else {
        return Err("replace_text handler received wrong delta".into());
    };
    let path = resolve_delta_path(path, roots, true)?;
    if !delta_apply_is_within_roots(&path, allowed_write_roots) {
        return Err(
            format!("replace_text refused outside allowed roots: {}", path.display()),
        );
    }
    let content = fs::read_to_string(&path)
        .map_err(|e| format!("replace_text failed to read {}: {e}", path.display()))?;
    let occurrences = content.match_indices(find).count();
    if occurrences == 0 {
        if content.contains(replace) {
            return Ok(
                format!("replace_text {} (no-op, already replaced)", path.display()),
            );
        }
        return Err(format!("replace_text did not find target in {}", path.display()));
    }
    let updated = content.replace(find, replace);
    fs::write(&path, updated)
        .map_err(|e| format!("replace_text failed to write {}: {e}", path.display()))?;
    Ok(format!("replace_text {} ({} replacements)", path.display(), occurrences))
}
fn apply_delete_file(
    delta: &ExecutionDelta,
    roots: &[PathBuf],
    allowed_write_roots: &[PathBuf],
    _max_output_lines: usize,
) -> Result<String, String> {
    let ExecutionDelta::DeleteFile { path } = delta else {
        return Err("delete_file handler received wrong delta".into());
    };
    let path = resolve_delta_path(path, roots, true)?;
    if !delta_apply_is_within_roots(&path, allowed_write_roots) {
        return Err(
            format!("delete_file refused outside allowed roots: {}", path.display()),
        );
    }
    if path.is_dir() {
        return Err(
            format!("delete_file refused to remove directory {}", path.display()),
        );
    }
    if path.exists() {
        fs::remove_file(&path)
            .map_err(|e| format!("delete_file failed for {}: {e}", path.display()))?;
        Ok(format!("delete_file {} (removed)", path.display()))
    } else {
        Ok(format!("delete_file {} (no-op)", path.display()))
    }
}

use serde::{Deserialize, Serialize};
