    pub failure_type: String,
    pub signature: String,
    pub iteration: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
struct FailureStoreFailureFile {
    pub template_hash: String,
    pub failures: Vec<FailureStoreFailureEntry>,
}
pub struct FailureStore {
    path: PathBuf,
    log_path: PathBuf,
    data: FailureStoreFailureFile,
}
#[derive(Debug, Clone)]
pub struct FailureStoreFailureStats {
    pub total: usize,
    pub cycle: usize,
    pub deadlock: usize,
    pub failure_pattern_rate: f64,
    pub cycle_frequency: f64,
    pub deadlock_rate: f64,
}
#[derive(Debug, Clone)]
pub struct FailureStoreConstraint {
    pub signature: String,
    pub rule: FailureStoreConstraintRule,
}
#[derive(Debug, Clone)]
pub enum FailureStoreConstraintRule {
    NoCycle,
    NoUnreachable,
    CapabilityConflict,
    InvalidDependency,
    PatternRewrite { pattern: String, replacement: String },
    SignatureBan,
}
impl FailureStore {
    pub fn snapshot_store_load(template_hash: &str) -> Self {
        let dir = Path::new(TEMPLATE_ROOT).join("failures");
        let path = dir.join(format!("{}_failures.json", template_hash));
        let log_path = dir.join("failure_log.json");
        let data = std::fs::read_to_string(&path)
            .ok()
            .and_then(|s| serde_json::from_str::<FailureStoreFailureFile>(&s).ok())
            .unwrap_or_else(|| FailureStoreFailureFile {
                template_hash: template_hash.to_string(),
                failures: Vec::new(),
            });
        Self { path, log_path, data }
    }
    pub fn contains(&self, signature: &str) -> bool {
        self.data.failures.iter().any(|f| f.signature == signature)
    }
    pub fn failure_count(&self) -> usize {
        self.data.failures.len()
    }
    pub fn stats(&self) -> FailureStoreFailureStats {
        let mut cycle = 0usize;
        let mut deadlock = 0usize;
        for f in &self.data.failures {
            match f.failure_type.as_str() {
                "cycle" => cycle += 1,
                "deadlock" => deadlock += 1,
                _ => {}
            }
        }
        let total = self.data.failures.len();
        let denom = total.max(1) as f64;
        FailureStoreFailureStats {
            total,
            cycle,
            deadlock,
            failure_pattern_rate: (total as f64 / 10.0).min(1.0),
            cycle_frequency: cycle as f64 / denom,
            deadlock_rate: deadlock as f64 / denom,
        }
    }
    pub fn constraints(
        &self,
        threshold: usize,
        max_constraints: usize,
    ) -> Vec<FailureStoreConstraint> {
        let mut by_type: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
        for f in &self.data.failures {
            *by_type.entry(f.failure_type.as_str()).or_insert(0) += 1;
        }
        let mut out = Vec::new();
        for f in &self.data.failures {
            if out.len() >= max_constraints {
                break;
            }
            if let Some(count) = by_type.get(f.failure_type.as_str()) {
                if *count < threshold {
                    continue;
                }
            }
            let rule = match f.failure_type.as_str() {
                "cycle" => FailureStoreConstraintRule::NoCycle,
                "deadlock" | "blocked" => FailureStoreConstraintRule::NoUnreachable,
                "invalid_authority" => FailureStoreConstraintRule::CapabilityConflict,
                "dependency_order" => FailureStoreConstraintRule::InvalidDependency,
                "verify_loop" => {
                    FailureStoreConstraintRule::PatternRewrite {
                        pattern: "cargo build".to_string(),
                        replacement: "cargo check".to_string(),
                    }
                }
                _ => FailureStoreConstraintRule::SignatureBan,
            };
            out.push(FailureStoreConstraint {
                signature: f.signature.clone(),
                rule,
            });
        }
        out
    }
    pub fn record(
        &mut self,
        signature: String,
        failure_type: &str,
        graph: &ExecutionGraph,
        iteration: u64,
    ) {
        if self.contains(&signature) {
            return;
        }
        let entry = FailureStoreFailureEntry {
            signature: signature.clone(),
            failure_type: failure_type.to_string(),
            node_count: graph.nodes.len(),
            edge_count: graph.nodes.iter().map(|n| n.deps.len()).sum(),
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs())
                .unwrap_or(0),
        };
        self.data.failures.push(entry);
        self.persist();
        self.append_log(FailureStoreFailureLogEntry {
            template_hash: self.data.template_hash.clone(),
            failure_type: failure_type.to_string(),
            signature,
            iteration,
        });
    }
    pub fn record_graph(
        &mut self,
        failure_type: &str,
        graph: &ExecutionGraph,
        iteration: u64,
    ) {
        let signature = hash_graph_structure(graph);
        self.record(signature, failure_type, graph, iteration);
    }
    fn persist(&self) {
        if let Ok(pretty) = serde_json::to_string_pretty(&self.data) {
            let _ = std::fs::create_dir_all(
                self.path.parent().unwrap_or(Path::new(".")),
            );
            let _ = std::fs::write(&self.path, pretty);
        }
    }
    fn append_log(&self, entry: FailureStoreFailureLogEntry) {
        if let Ok(line) = serde_json::to_string(&entry) {
            let _ = std::fs::create_dir_all(
                self.log_path.parent().unwrap_or(Path::new(".")),
            );
            let _ = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&self.log_path)
                .and_then(|mut f| f.write_all(format!("{}\n", line).as_bytes()));
        }
    }
}

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::Path;
const CACHE_PATH: &str = "/workspace/ai_sandbox/canon/agent_logs/goal_embeddings.json";
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GoalEmbedding {
    pub vector: Vec<f32>,
}
pub fn goal_embedding_embed_goal(goal: &str, dim: usize) -> GoalEmbedding {
    let dim = dim.max(8);
    let mut vec = vec![0.0f32; dim];
    for token in goal.split_whitespace() {
        let mut h = goal_embedding_fnv64(token.as_bytes());
        let sign = if (h & 1) == 0 { 1.0 } else { -1.0 };
        let idx = (h as usize) % dim;
        vec[idx] += sign;
        h = h.wrapping_mul(0x9e3779b97f4a7c15);
        let idx2 = (h as usize) % dim;
        vec[idx2] += sign * 0.5;
    }
    GoalEmbedding { vector: vec }
}
pub fn goal_embedding_cosine_similarity(a: &[f32], b: &[f32]) -> f64 {
    if a.is_empty() || b.is_empty() || a.len() != b.len() {
        return 0.0;
    }
    let mut dot = 0.0f64;
    let mut na = 0.0f64;
    let mut nb = 0.0f64;
    for (x, y) in a.iter().zip(b.iter()) {
        dot += (*x as f64) * (*y as f64);
        na += (*x as f64) * (*x as f64);
        nb += (*y as f64) * (*y as f64);
    }
    if na == 0.0 || nb == 0.0 {
        0.0
    } else {
        (dot / (na.sqrt() * nb.sqrt())).clamp(0.0, 1.0)
    }
}
pub fn goal_embedding_load_cache() -> HashMap<String, Vec<f32>> {
    std::fs::read_to_string(CACHE_PATH)
        .ok()
        .and_then(|s| serde_json::from_str::<HashMap<String, Vec<f32>>>(&s).ok())
        .unwrap_or_default()
}
pub fn goal_embedding_save_cache(cache: &HashMap<String, Vec<f32>>) {
    if let Ok(pretty) = serde_json::to_string_pretty(cache) {
        let _ = std::fs::create_dir_all(
            Path::new(CACHE_PATH).parent().unwrap_or(Path::new(".")),
        );
        let _ = std::fs::write(CACHE_PATH, pretty);
    }
}
pub fn goal_embedding_goal_hash(goal: &str) -> String {
    format!("{:016x}", goal_embedding_fnv64(goal.as_bytes()))
}
fn goal_embedding_fnv64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

