pub fn compute_graph_features(graph: &dag::ExecutionGraph) -> GraphFeatureVector {
    let signals = graph_analysis_compute_graph_signals(graph);
    let nodes = graph.nodes.len();
    let edges = graph.nodes.iter().map(|n| n.deps.len()).sum();
    let depth = graph_max_depth(graph);
    let failed = graph
        .nodes
        .iter()
        .filter(|n| n.status == dag::NodeStatus::Failed)
        .count();
    let failure_rate = if nodes == 0 { 0.0 } else { failed as f64 / nodes as f64 };
    #[cfg(feature = "cuda")]
    let (
        root_count,
        leaf_count,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
    ) = {
        let mut adj: Vec<Vec<usize>> = vec![Vec::new(); nodes];
        let mut id_to_idx: HashMap<&str, usize> = HashMap::new();
        for (i, n) in graph.nodes.iter().enumerate() {
            id_to_idx.insert(n.id.as_str(), i);
        }
        for n in &graph.nodes {
            if let Some(&to) = id_to_idx.get(n.id.as_str()) {
                for dep in &n.deps {
                    if let Some(&from) = id_to_idx.get(dep.as_str()) {
                        adj[from].push(to);
                    }
                }
            }
        }
        let csr = Csr::from_adj(&adj);
        let (indegree, outdegree) = algorithms::graph::feature_gpu::indegree_outdegree(
            &csr,
        );
        let status = graph.nodes.iter().map(|n| n.status as u8).collect::<Vec<_>>();
        let priority = graph.nodes.iter().map(|n| n.priority as u16).collect::<Vec<_>>();
        let budget = graph
            .nodes
            .iter()
            .map(|n| n.budget.unwrap_or(0) as u32)
            .collect::<Vec<_>>();
        let retry = graph
            .nodes
            .iter()
            .map(|n| n.readonly_fail_count as u32)
            .collect::<Vec<_>>();
        let mut has_verify = Vec::with_capacity(nodes);
        let mut has_mutate = Vec::with_capacity(nodes);
        let mut has_observe = Vec::with_capacity(nodes);
        let mut node_type = Vec::with_capacity(nodes);
        let mut max_completed_iter = 0u64;
        let mut completed = 0usize;
        for n in &graph.nodes {
            let mut v = 0u8;
            let mut m = 0u8;
            let mut o = 0u8;
            for cap in &n.required_capabilities {
                match cap.class() {
                    super::capability::CapabilityMode::Verify => v = 1,
                    super::capability::CapabilityMode::Mutate => m = 1,
                    super::capability::CapabilityMode::Observe => o = 1,
                }
            }
            has_verify.push(v);
            has_mutate.push(m);
            has_observe.push(o);
            node_type
                .push(
                    if n.node_type == decompose::DecomposeNodeType::Analysis {
                        0
                    } else {
                        1
                    },
                );
            if n.status == dag::NodeStatus::Completed {
                completed += 1;
                if let Some(t) = n.completed_iter {
                    max_completed_iter = max_completed_iter.max(t);
                }
            }
        }
        let stats = algorithms::graph::feature_gpu::feature_stats_gpu(
            &status,
            &indegree,
            &outdegree,
            &priority,
            &budget,
            &retry,
            &has_verify,
            &has_mutate,
            &has_observe,
            &node_type,
        );
        let avg_out_degree = if nodes == 0 { 0.0 } else { edges as f64 / nodes as f64 };
        let avg_in_degree = avg_out_degree;
        let branching_factor = if stats.non_leaf_count == 0 {
            0.0
        } else {
            stats.outdegree_sum as f64 / stats.non_leaf_count as f64
        };
        let verify_to_mutate_ratio = if stats.mutate_count == 0 {
            0.0
        } else {
            stats.verify_count as f64 / stats.mutate_count as f64
        };
        let observe_to_mutate_ratio = if stats.mutate_count == 0 {
            0.0
        } else {
            stats.observe_count as f64 / stats.mutate_count as f64
        };
        let total = nodes.max(1) as f64;
        let p_a = stats.analysis_count as f64 / total;
        let p_r = stats.render_count as f64 / total;
        let h = |p: f64| if p <= 0.0 { 0.0 } else { -p * p.ln() };
        let node_type_entropy = h(p_a) + h(p_r);
        let avg_node_priority = if nodes == 0 {
            0.0
        } else {
            stats.priority_sum as f64 / nodes as f64
        };
        let avg_node_budget = if nodes == 0 {
            0.0
        } else {
            stats.budget_sum as f64 / nodes as f64
        };
        let blocked_fraction = if nodes == 0 {
            0.0
        } else {
            stats.blocked_count as f64 / nodes as f64
        };
        let ready_fraction = if nodes == 0 {
            0.0
        } else {
            stats.ready_count as f64 / nodes as f64
        };
        let failed_fraction = if nodes == 0 {
            0.0
        } else {
            stats.failed_count as f64 / nodes as f64
        };
        let completion_velocity = if completed == 0 {
            0.0
        } else {
            completed as f64 / (max_completed_iter.max(1) as f64 + 1.0)
        };
        let retry_rate = if nodes == 0 {
            0.0
        } else {
            stats.retry_sum as f64 / nodes as f64
        };
        (
            stats.root_count as usize,
            stats.leaf_count as usize,
            avg_out_degree,
            avg_in_degree,
            branching_factor,
            verify_to_mutate_ratio,
            observe_to_mutate_ratio,
            node_type_entropy,
            avg_node_priority,
            avg_node_budget,
            blocked_fraction,
            ready_fraction,
            failed_fraction,
            completion_velocity,
            retry_rate,
        )
    };
    #[cfg(not(feature = "cuda"))]
    let (
        root_count,
        leaf_count,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
    ) = {
        let mut indegree = vec![0usize; nodes];
        let mut outdegree = vec![0usize; nodes];
        let mut id_to_idx: HashMap<&str, usize> = HashMap::new();
        for (i, n) in graph.nodes.iter().enumerate() {
            id_to_idx.insert(n.id.as_str(), i);
            indegree[i] = n.deps.len();
        }
        for n in &graph.nodes {
            for dep in &n.deps {
                if let Some(&idx) = id_to_idx.get(dep.as_str()) {
                    outdegree[idx] += 1;
                }
            }
        }
        let root_count = graph.nodes.iter().filter(|n| n.deps.is_empty()).count();
        let leaf_count = outdegree.iter().filter(|&&d| d == 0).count();
        let avg_out_degree = if nodes == 0 { 0.0 } else { edges as f64 / nodes as f64 };
        let avg_in_degree = avg_out_degree;
        let branching_factor = {
            let non_leaf = outdegree.iter().filter(|&&d| d > 0).count();
            if non_leaf == 0 {
                0.0
            } else {
                outdegree.iter().sum::<usize>() as f64 / non_leaf as f64
            }
        };
        let mut verify_count = 0usize;
        let mut mutate_count = 0usize;
        let mut observe_count = 0usize;
        let mut analysis_count = 0usize;
        let mut render_count = 0usize;
        let mut priority_sum = 0f64;
        let mut budget_sum = 0f64;
        let mut blocked = 0usize;
        let mut ready = 0usize;
        let mut failed_count = 0usize;
        let mut completed = 0usize;
        let mut retry_total = 0f64;
        let mut max_completed_iter = 0u64;
        for n in &graph.nodes {
            if n.node_type == decompose::NodeType::Analysis {
                analysis_count += 1;
            } else {
                render_count += 1;
            }
            for cap in &n.required_capabilities {
                match cap.class() {
                    super::capability::CapabilityClass::Verify => verify_count += 1,
                    super::capability::CapabilityClass::Mutate => mutate_count += 1,
                    super::capability::CapabilityClass::Observe => observe_count += 1,
                }
            }
            priority_sum += n.priority as f64;
            if let Some(b) = n.budget {
                budget_sum += b as f64;
            }
            match n.status {
                dag::Status::Blocked => blocked += 1,
                dag::Status::Ready => ready += 1,
                dag::Status::Failed => failed_count += 1,
                dag::Status::Completed => {
                    completed += 1;
                    if let Some(t) = n.completed_iter {
                        max_completed_iter = max_completed_iter.max(t);
                    }
                }
                _ => {}
            }
            retry_total += n.readonly_fail_count as f64;
        }
        let verify_to_mutate_ratio = if mutate_count == 0 {
            0.0
        } else {
            verify_count as f64 / mutate_count as f64
        };
        let observe_to_mutate_ratio = if mutate_count == 0 {
            0.0
        } else {
            observe_count as f64 / mutate_count as f64
        };
        let node_type_entropy = {
            let total = nodes.max(1) as f64;
            let p_a = analysis_count as f64 / total;
            let p_r = render_count as f64 / total;
            let h = |p: f64| if p <= 0.0 { 0.0 } else { -p * p.ln() };
            h(p_a) + h(p_r)
        };
        let avg_node_priority = if nodes == 0 {
            0.0
        } else {
            priority_sum / nodes as f64
        };
        let avg_node_budget = if nodes == 0 { 0.0 } else { budget_sum / nodes as f64 };
        let blocked_fraction = if nodes == 0 {
            0.0
        } else {
            blocked as f64 / nodes as f64
        };
        let ready_fraction = if nodes == 0 { 0.0 } else { ready as f64 / nodes as f64 };
        let failed_fraction = if nodes == 0 {
            0.0
        } else {
            failed_count as f64 / nodes as f64
        };
        let completion_velocity = if completed == 0 {
            0.0
        } else {
            completed as f64 / (max_completed_iter.max(1) as f64 + 1.0)
        };
        let retry_rate = if nodes == 0 { 0.0 } else { retry_total / nodes as f64 };
        (
            root_count,
            leaf_count,
            avg_out_degree,
            avg_in_degree,
            branching_factor,
            verify_to_mutate_ratio,
            observe_to_mutate_ratio,
            node_type_entropy,
            avg_node_priority,
            avg_node_budget,
            blocked_fraction,
            ready_fraction,
            failed_fraction,
            completion_velocity,
            retry_rate,
        )
    };
    GraphFeatureVector {
        nodes,
        edges,
        depth,
        scc_count: signals.sccs.len(),
        failure_rate,
        reward_trend: 0.0,
        avg_out_degree,
        avg_in_degree,
        branching_factor,
        leaf_count,
        root_count,
        verify_to_mutate_ratio,
        observe_to_mutate_ratio,
        node_type_entropy,
        avg_node_priority,
        avg_node_budget,
        blocked_fraction,
        ready_fraction,
        failed_fraction,
        completion_velocity,
        retry_rate,
        failure_pattern_rate: 0.0,
        cycle_frequency: 0.0,
        deadlock_rate: 0.0,
    }
}
pub fn graph_analysis_normalize_features(
