        .failure_rate, f.reward_trend, f.avg_out_degree / 10.0, f.avg_in_degree / 10.0, f
        .branching_factor / 10.0, f.leaf_count as f64 / denom_nodes, f.root_count as f64
        / denom_nodes, f.verify_to_mutate_ratio, f.observe_to_mutate_ratio, f
        .node_type_entropy, f.avg_node_priority / 10.0, f.avg_node_budget / 10.0, f
        .blocked_fraction, f.ready_fraction, f.failed_fraction, f.completion_velocity, f
        .retry_rate, f.failure_pattern_rate, f.cycle_frequency, f.deadlock_rate,
