pub fn score_node_utility(graph: &dag::ExecutionGraph, node_id: &str, iter: u64) -> f64 {
    let node = match graph.nodes.iter().find(|n| n.id == node_id) {
        Some(n) => n,
        None => return 0.0,
    };
    let dependents = graph
        .nodes
        .iter()
        .filter(|n| n.deps.iter().any(|d| d == node_id))
        .count();
    let completion_value = if node.status == dag::NodeStatus::Completed
        && node.error.is_none()
    {
        1.0
    } else {
        0.0
    };
    let age = node.completed_iter.map(|t| iter.saturating_sub(t)).unwrap_or(0) as f64;
    0.6 * dependents as f64 + 0.3 * completion_value - 0.1 * age
}
pub fn graph_analysis_edge_count(graph: &dag::ExecutionGraph) -> usize {
    graph.nodes.iter().map(|n| n.deps.len()).sum()
}
pub fn hash_graph_structure(graph: &dag::ExecutionGraph) -> String {
    let mut nodes = graph
        .nodes
        .iter()
        .map(|n| {
            let mut caps: Vec<PipelineCapability> = n.required_capabilities.clone();
            caps.sort_by_key(|c| format!("{:?}", c));
            (n.id.clone(), format!("{:?}", n.node_type), caps)
        })
        .collect::<Vec<_>>();
    nodes.sort_by(|a, b| a.0.cmp(&b.0));
    let mut edges = Vec::new();
    for n in &graph.nodes {
        for dep in &n.deps {
            edges.push((dep.clone(), n.id.clone()));
        }
    }
    edges.sort();
    let mut hasher = GraphAnalysisFnv64::new();
    hasher.write(b"nodes");
    for (id, node_type, caps) in nodes {
        hasher.write(id.as_bytes());
        hasher.write(node_type.as_bytes());
        for cap in caps {
            hasher.write(format!("{:?}", cap).as_bytes());
        }
    }
    hasher.write(b"edges");
    for (from, to) in edges {
        hasher.write(from.as_bytes());
        hasher.write(to.as_bytes());
    }
    format!("{:016x}", hasher.finish())
}
fn graph_max_depth(graph: &dag::ExecutionGraph) -> usize {
    if graph.nodes.is_empty() {
        return 0;
    }
    let id_to_idx: HashMap<&str, usize> = graph
        .nodes
        .iter()
        .enumerate()
        .map(|(i, n)| (n.id.as_str(), i))
        .collect();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for (idx, node) in graph.nodes.iter().enumerate() {
        for dep in &node.deps {
            if let Some(&j) = id_to_idx.get(dep.as_str()) {
                adj[j].push(idx);
            }
        }
    }
    let depth = gpu_kernels::graph_cpu_kernels_compute_depth(&adj);
    depth.into_iter().map(|d| d.max(0) as usize).max().unwrap_or(0)
}
struct GraphAnalysisFnv64 {
    state: u64,
}
impl GraphAnalysisFnv64 {
    fn new() -> Self {
        Self { state: 0xcbf29ce484222325 }
    }
    fn write(&mut self, bytes: &[u8]) {
        for b in bytes {
            self.state ^= *b as u64;
            self.state = self.state.wrapping_mul(0x100000001b3);
        }
    }
    fn finish(&self) -> u64 {
        self.state
    }
}

use std::path::Path;
use anyhow::Result;
use super::dag;
use super::graph_algo::{
    graph_analysis_emit_planned_graph, score_node_utility,
    graph_analysis_run_graph_algorithms,
};
use super::graph_runtime::{validate_graph_semantics, prune_unreachable_nodes};
pub struct GraphRepairMaintenanceCtx<'a> {
    pub graph: &'a mut dag::ExecutionGraph,
    pub log_dir: &'a Path,
    pub iter: u64,
    pub features_retry_rate: f64,
    pub features_failed_fraction: f64,
    pub features_branching_factor: f64,
    pub prune_unlinked: bool,
    pub auto_prune: bool,
    pub prune_min_age: u64,
    pub prune_threshold: f64,
    pub recovery_retry_rate_threshold: f64,
    pub recovery_failed_fraction_threshold: f64,
}
pub(crate) fn prune_low_utility_nodes(
    graph: &mut dag::ExecutionGraph,
    iter: u64,
    auto_prune: bool,
    prune_min_age: u64,
    prune_threshold: f64,
) {
    if !auto_prune {
        return;
    }
    let mut parents = std::collections::HashSet::new();
    for node in &graph.nodes {
        for dep in &node.deps {
            parents.insert(dep.clone());
        }
    }
    let mut pruned = Vec::new();
    for node in &graph.nodes {
        if node.status != dag::NodeStatus::Completed {
            continue;
        }
        if node.deps.is_empty() {
            continue;
        }
        if parents.contains(&node.id) {
            continue;
        }
        let age = node.completed_iter.map(|t| iter.saturating_sub(t)).unwrap_or(0);
        if age < prune_min_age {
            continue;
        }
        let util = score_node_utility(graph, &node.id, iter);
        if util < prune_threshold {
            pruned.push(node.id.clone());
        }
    }
    if pruned.is_empty() {
        return;
    }
    graph.nodes.retain(|n| !pruned.contains(&n.id));
    for node in &mut graph.nodes {
        node.deps.retain(|d| !pruned.contains(d));
    }
    graph.rebuild_index();
}
pub(crate) fn recover_from_failures(graph: &mut dag::ExecutionGraph) {
    for node in &mut graph.nodes {
        if node.status == dag::NodeStatus::Failed {
            node.status = dag::NodeStatus::Pending;
            node.readonly_fail_count = 0;
            node.error = None;
            node.result = None;
        }
    }
    graph.rebuild_index();
}
pub fn repair_graph(ctx: GraphRepairMaintenanceCtx<'_>) -> Result<()> {
    super::capability_pipeline_ensure_unique_node_ids(&mut ctx.graph.nodes);
    let iter_u32 = u32::try_from(ctx.iter).unwrap_or(u32::MAX);
    graph_analysis_emit_planned_graph(ctx.graph, ctx.log_dir, iter_u32);
    graph_analysis_run_graph_algorithms(ctx.graph, ctx.log_dir, iter_u32);
    if ctx.prune_unlinked {
        prune_unreachable_nodes(ctx.graph);
    }
    validate_graph_semantics(ctx.graph)?;
    prune_low_utility_nodes(
        ctx.graph,
        ctx.iter,
        ctx.auto_prune,
        ctx.prune_min_age,
        ctx.prune_threshold,
    );
    let risk = graph_repair_risk_score(
        ctx.features_retry_rate,
        ctx.features_failed_fraction,
        ctx.features_branching_factor,
    );
    let threshold = (ctx.recovery_retry_rate_threshold
        + ctx.recovery_failed_fraction_threshold) / 2.0;
    if risk > threshold {
        recover_from_failures(ctx.graph);
    }
    Ok(())
}
fn graph_repair_risk_score(
    retry_rate: f64,
    failed_fraction: f64,
    branching_factor: f64,
) -> f64 {
    let w1 = 0.5;
    let w2 = 0.4;
    let w3 = 0.1;
    let branching_norm = (branching_factor / 4.0).min(1.0);
    (w1 * retry_rate) + (w2 * failed_fraction) + (w3 * branching_norm)
}

use anyhow::Result;
use std::collections::HashMap;
use std::path::Path;
use super::dag;
use super::dag::ContextSnapshotNode;
use super::decompose;
#[cfg(feature = "cuda")]
use algorithms::graph::model_checking;
use algorithms::graph::{csr::Csr, reachability, scc, topological_sort};
struct GraphRuntimeGraphKernels {
    adj: Vec<Vec<usize>>,
    csr: Csr,
    topo: Vec<usize>,
    sccs: Vec<Vec<usize>>,
}
fn graph_runtime_build_kernels(graph: &dag::ExecutionGraph) -> GraphRuntimeGraphKernels {
    let id_to_idx: HashMap<&str, usize> = graph
        .nodes
        .iter()
        .enumerate()
        .map(|(i, n)| (n.id.as_str(), i))
        .collect();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for n in &graph.nodes {
        let to = match id_to_idx.get(n.id.as_str()) {
            Some(v) => *v,
            None => continue,
        };
        for dep in &n.deps {
            if let Some(from) = id_to_idx.get(dep.as_str()) {
                adj[*from].push(to);
            }
        }
    }
    let csr = Csr::from_adj(&adj);
    let topo = topological_sort::topological_sort(&adj);
    let sccs = scc::kosaraju_scc(&adj);
    GraphRuntimeGraphKernels {
        adj,
        csr,
        topo,
        sccs,
    }
}
fn graph_runtime_prune_roots(kernels: &GraphRuntimeGraphKernels) -> Vec<usize> {
    let all: std::collections::HashSet<usize> = kernels
        .topo
        .iter()
        .chain(kernels.sccs.iter().flatten())
        .copied()
        .collect();
    all.into_iter().filter(|&i| !kernels.adj[i].is_empty()).collect()
}
pub(crate) fn collect_execution_context(
    graph: &dag::ExecutionGraph,
    node_id: &str,
    radius: usize,
) -> Vec<ContextSnapshotNode> {
    if radius == 0 {
        return Vec::new();
    }
    let id_to_idx: HashMap<&str, usize> = graph
        .nodes
        .iter()
        .enumerate()
        .map(|(i, n)| (n.id.as_str(), i))
        .collect();
    let mut rev_adj: Vec<Vec<usize>> = vec![Vec::new(); graph.nodes.len()];
    for (idx, node) in graph.nodes.iter().enumerate() {
        for dep in &node.deps {
            if let Some(dep_idx) = id_to_idx.get(dep.as_str()) {
                rev_adj[idx].push(*dep_idx);
            }
        }
    }
    let csr = Csr::from_adj(&rev_adj);
    let start = graph.nodes.iter().position(|n| n.id == node_id);
    let roots: Vec<usize> = start.into_iter().collect();
    let reach = reachability::reachability_bounded(&csr, &roots, radius);
    let by_id: HashMap<&str, &dag::ExecutionNode> = graph
        .nodes
        .iter()
        .map(|n| (n.id.as_str(), n))
        .collect();
    let failure_summary = graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(i, n)| {
            reach.get(*i).copied().unwrap_or(false)
                && n.status == dag::NodeStatus::Failed
        })
        .filter_map(|(_, n)| n.error.as_deref().map(|e| format!("{}: {}", n.id, e)))
        .collect::<Vec<_>>()
        .join("\n");
    let failure_summary = if failure_summary.is_empty() {
        None
    } else {
        Some(failure_summary)
    };
    graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(i, _)| reach.get(*i).copied().unwrap_or(false))
        .map(|(_, n)| {
            let causal_summary = n
                .deps
                .iter()
                .filter_map(|dep_id| by_id.get(dep_id.as_str()))
                .filter(|dep| dep.status == dag::NodeStatus::Completed)
                .filter_map(|dep| dep.result.as_deref())
                .collect::<Vec<_>>()
                .join("\n---\n");
            let causal_summary = if causal_summary.is_empty() {
                None
            } else {
                Some(causal_summary)
            };
            ContextSnapshotNode {
                id: n.id.clone(),
                description: n.description.clone(),
                node_type: n.node_type,
                deps: n.deps.clone(),
                required_capabilities: n.required_capabilities.clone(),
                status: n.status,
                result: n.result.clone(),
                error: n.error.clone(),
                causal_summary,
                failure_summary: failure_summary.clone(),
            }
        })
        .collect()
}
pub(crate) fn prune_unreachable_nodes(graph: &mut dag::ExecutionGraph) {
    if graph.nodes.is_empty() {
        return;
    }
    let kernels = graph_runtime_build_kernels(graph);
    let roots = graph_runtime_prune_roots(&kernels);
    if roots.is_empty() {
        return;
    }
    let reach = reachability::reachability_gpu(&kernels.csr, &roots);
    let mut next = Vec::with_capacity(graph.nodes.len());
    for (idx, node) in graph.nodes.iter().enumerate() {
        if reach.get(idx).copied().unwrap_or(false) {
            next.push(node.clone());
        }
    }
    graph.nodes = next;
}
pub(crate) fn validate_graph_semantics(graph: &dag::ExecutionGraph) -> Result<()> {
    validate_graph_invariants(graph)?;
    let kernels = graph_runtime_build_kernels(graph);
    let analysis_roots: Vec<usize> = graph
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(i, n)| {
            (n.node_type == decompose::DecomposeNodeType::Analysis).then_some(i)
        })
        .collect();
    let reach = reachability::reachability_gpu(&kernels.csr, &analysis_roots);
    for (idx, n) in graph.nodes.iter().enumerate() {
        if n.node_type == decompose::DecomposeNodeType::Render
            && !reach.get(idx).copied().unwrap_or(false)
        {
            return Err(
                anyhow::anyhow!("render node {} not reachable from analysis node", n.id),
            );
        }
    }
    let invariant_mask: Vec<u8> = graph
        .nodes
        .iter()
        .map(|n| {
            let ok = !n.description.trim().is_empty()
                && !n.required_capabilities.is_empty();
            ok as u8
        })
        .collect();
    #[cfg(feature = "cuda")]
    {
        let ok = model_checking::model_check_gpu(
            &kernels.csr,
            &analysis_roots,
            &invariant_mask,
        );
        if !ok {
            return Err(
                anyhow::anyhow!(
                    "model check failed: invariant violation on reachable node"
                ),
            );
        }
    }
    #[cfg(not(feature = "cuda"))]
    {
        for (idx, ok) in invariant_mask.iter().enumerate() {
            if reach.get(idx).copied().unwrap_or(false) && *ok == 0 {
                return Err(
                    anyhow::anyhow!(
                        "model check failed: invariant violation on reachable node"
                    ),
                );
            }
        }
    }
    Ok(())
}
fn validate_graph_invariants(graph: &dag::ExecutionGraph) -> Result<()> {
    if graph.nodes.is_empty() {
        return Ok(());
    }
    let kernels = graph_runtime_build_kernels(graph);
    let invariant_mask: Vec<u8> = graph
        .nodes
        .iter()
        .map(|n| {
            let ok = !n.id.trim().is_empty() && !n.description.trim().is_empty()
                && !n.required_capabilities.is_empty()
                && !n.deps.iter().any(|d| d == &n.id);
            ok as u8
        })
        .collect();
    let roots: Vec<usize> = (0..graph.nodes.len()).collect();
    #[cfg(feature = "cuda")]
    {
        let ok = model_checking::model_check_gpu(&kernels.csr, &roots, &invariant_mask);
        if !ok {
            return Err(anyhow::anyhow!("assertion check failed: invariant violated"));
        }
    }
    #[cfg(not(feature = "cuda"))]
    {
        for (idx, ok) in invariant_mask.iter().enumerate() {
            if *ok == 0 {
                return Err(
                    anyhow::anyhow!(
                        "assertion check failed: invariant violated at node {}", graph
                        .nodes[idx].id
                    ),
                );
            }
        }
    }
    Ok(())
}

