async fn llm_client_call_agent_json_with_retry_inner(
    bridge: &WsBridge,
    endpoint_id: &str,
    url: &str,
    stateful: bool,
    prompt: &str,
    role_schema: &str,
    phase: &str,
    node_id: Option<&str>,
    tabs: &TabManagerHandle,
    max_tabs: usize,
    tab_cooldown_ms: u64,
    max_retries: u32,
    delay_secs: u64,
    allow_req_id_mismatch: bool,
) -> Result<Value> {
    let mut last_err: Option<anyhow::Error> = None;
    for attempt in 0..max_retries {
        let start = tab_manager_now_ms();
        tab_manager_log_llm(
            format!(
                "phase={} endpoint={} attempt={} start", phase, endpoint_id, attempt + 1
            ),
        );
        match llm_client_call_agent_json_inner(
                bridge,
                endpoint_id,
                url,
                stateful,
                prompt,
                role_schema,
                phase,
                node_id,
                tabs,
                max_tabs,
                tab_cooldown_ms,
                allow_req_id_mismatch,
            )
            .await
        {
            Ok(v) => {
                let elapsed = tab_manager_now_ms().saturating_sub(start);
                tab_manager_log_llm(
                    format!(
                        "phase={} endpoint={} attempt={} ok elapsed_ms={}", phase,
                        endpoint_id, attempt + 1, elapsed
                    ),
                );
                return Ok(v);
            }
            Err(e) => {
                let elapsed = tab_manager_now_ms().saturating_sub(start);
                tab_manager_log_llm(
                    format!(
                        "phase={} endpoint={} attempt={} error={} elapsed_ms={}", phase,
                        endpoint_id, attempt + 1, e, elapsed
                    ),
                );
                last_err = Some(e);
                tokio::time::sleep(std::time::Duration::from_secs(delay_secs)).await;
            }
        }
    }
    Err(last_err.unwrap_or_else(|| anyhow::anyhow!("llm retries exhausted")))
}
