    let mut routes = ROUTES.lock().await;
    routes.insert(req_id, node_id.to_string());
}
pub async fn response_router_resolve(req_id: u64) -> Option<String> {
    let mut routes = ROUTES.lock().await;
    routes.remove(&req_id)
}

